// ELEMENTS:
// 1. Fundo branco com o filete vermelho no topo
// 2. Eyebrow azul royal + título navy
// 3. Diagrama de Venn: círculo azul royal (items[0]) entra da esquerda, círculo vermelho (items[1])
//    da direita (times = s), a interseção enche-se de navy com um visto e o resultado (result) em resultAt
// 4. Pílula navy com a conclusão (sub)
import React, { useId } from "react";
import { AbsoluteFill, useCurrentFrame, interpolate, Easing } from "remotion";
import { FONTS } from "../style-tokens";
import type { PrimitiveProps } from "../primitives";

const NAVY = "#001F44";
const BLUE = "#013BA9";
const RED = "#DE212B";
const WHITE = "#FFFFFF";
const EASE = Easing.bezier(0.25, 0.1, 0.25, 1);
const BACK = Easing.out(Easing.back(1.4));
const clamp = { extrapolateLeft: "clamp", extrapolateRight: "clamp" } as const;

const VennCondicoes: React.FC<PrimitiveProps> = ({ anim, fps, format, frame: box }) => {
  const f = useCurrentFrame();
  const W = box.width;
  const u = format === "landscape" ? box.height / 1080 : format === "half" ? (box.height / 960) * 0.85 : W / 1080;
  const id = useId().replace(/:/g, "");
  const p = (anim.params ?? {}) as Record<string, unknown>;
  const eyebrow = String(p.eyebrow ?? "").trim();
  const title = String(p.title ?? anim.text ?? "").trim();
  const result = String(p.result ?? "").trim();
  const sub = String(p.sub ?? "").trim();
  const items = (Array.isArray(p.items) ? (p.items as unknown[]).map(String) : []).slice(0, 2).map((s) => {
    const i = s.indexOf(":");
    return i > 0 ? { label: s.slice(0, i).trim(), value: s.slice(i + 1).trim() } : { label: "", value: s.trim() };
  });
  const times = Array.isArray(p.times) ? (p.times as unknown[]).map(Number) : [];
  const t0 = Number.isFinite(times[0]) ? times[0] : 0.4;
  const t1 = Number.isFinite(times[1]) ? times[1] : 2;
  const tr = Number(p.resultAt ?? t1 + 2) || t1 + 2;

  const show = (delay: number, len = 0.7, easing = EASE): number =>
    interpolate(f, [Math.round(delay * fps), Math.round((delay + len) * fps)], [0, 1], { ...clamp, easing });
  const a = show(t0, 0.9, BACK);
  const b = show(t1, 0.9, BACK);
  const r = show(tr, 0.6, BACK);
  const R = 250, D = 170; // svg units: radius, centre offset
  const breathe = 1 + Math.sin(f / fps * 2.2) * 0.008;

  const label = (it: { label: string; value: string } | undefined, k: number, x: number) => it ? (
    <div style={{ position: "absolute", left: W / 2 + x * u - 150 * u, top: 0, width: 300 * u, height: "100%", display: "flex", flexDirection: "column", alignItems: "center", justifyContent: "center", textAlign: "center", color: WHITE, opacity: k, gap: 8 * u }}>
      <div style={{ fontFamily: FONTS.body, fontWeight: 600, fontSize: 24 * u, letterSpacing: "0.2em", textTransform: "uppercase", lineHeight: 1.3 }}>{it.label}</div>
      <div style={{ fontFamily: FONTS.display, fontWeight: 800, fontSize: 58 * u, lineHeight: 1.05 }}>{it.value}</div>
    </div>
  ) : null;

  return (
    <AbsoluteFill style={{ backgroundColor: WHITE, overflow: "hidden" }}>
      <AbsoluteFill style={{ justifyContent: "center", alignItems: "center", gap: 40 * u }}>
        <div style={{ display: "flex", flexDirection: "column", alignItems: "center", gap: 18 * u, opacity: show(0.05), textAlign: "center" }}>
          {eyebrow ? (
            <div style={{ display: "flex", alignItems: "center", gap: 18 * u, fontFamily: FONTS.body, fontWeight: 600, fontSize: 28 * u, letterSpacing: "0.32em", textTransform: "uppercase", color: BLUE }}>
              <div style={{ width: 44 * u, height: 3 * u, background: RED }} />
              {eyebrow}
            </div>
          ) : null}
          <div style={{ fontFamily: FONTS.display, fontWeight: 300, fontSize: 88 * u, lineHeight: 1.05, color: NAVY }}>{title}</div>
        </div>
        <div style={{ position: "relative", width: W, height: 620 * u }}>
          <svg width={W} height={620 * u} viewBox={`${-W / 2 / u} -310 ${W / u} 620`} style={{ position: "absolute", inset: 0, transform: `scale(${breathe})` }}>
            <defs>
              <clipPath id={`${id}a`}><circle cx={-D + (1 - a) * -500} cy={0} r={R} /></clipPath>
            </defs>
            <circle cx={-D + (1 - a) * -500} cy={0} r={R} fill={BLUE} opacity={a > 0 ? 0.95 : 0} />
            <circle cx={D + (1 - b) * 500} cy={0} r={R} fill={RED} opacity={b > 0 ? 0.95 : 0} />
            <circle cx={D + (1 - b) * 500} cy={0} r={R} fill={NAVY} clipPath={`url(#${id}a)`} opacity={r} />
            <circle cx={0} cy={0} r={(R - D) * 0.55 * r + 0.01} fill="none" stroke={WHITE} strokeWidth={3} opacity={r} />
            <path d="M-26 0 L-8 18 L28 -20" fill="none" stroke={WHITE} strokeWidth={8} strokeLinecap="round" strokeLinejoin="round" pathLength={1} strokeDasharray={1} strokeDashoffset={1 - show(tr + 0.3, 0.5)} />
          </svg>
          {label(items[0], show(t0 + 0.5), -D - 90)}
          {label(items[1], show(t1 + 0.5), D + 90)}
          {result ? (
            <div style={{ position: "absolute", left: 0, right: 0, bottom: -10 * u, textAlign: "center", fontFamily: FONTS.display, fontWeight: 800, fontSize: 56 * u, color: NAVY, opacity: r, transform: `translateY(${(1 - r) * 20 * u}px)` }}>{result}</div>
          ) : null}
        </div>
        {sub ? (
          <div style={{ background: NAVY, color: WHITE, borderRadius: 999, padding: `${20 * u}px ${44 * u}px`, fontFamily: FONTS.body, fontWeight: 600, fontSize: 32 * u, letterSpacing: "0.16em", textTransform: "uppercase", opacity: show(tr + 0.5), transform: `scale(${0.85 + 0.15 * show(tr + 0.5, 0.5, BACK)})` }}>{sub}</div>
        ) : null}
      </AbsoluteFill>
      <div style={{ position: "absolute", top: 0, left: 0, right: 0, height: 6 * u, background: RED }} />
    </AbsoluteFill>
  );
};

export default VennCondicoes;
